		resize(p,size,cf)	
		material(p,Enum.Material.Concrete)	
		color(p,Color3.fromRGB(130,130,130))	
		transparency(p,0)	
		anchor(p,true)	
		collide(p,true)	
		lock(p,true)	
		return p	
	end	


	local base = newPart(BASE_CF,BASE_SIZE)	
	name(base,"z238z realm")	


	newPart(	
		BASE_CF * CFrame.new(0, WALL_H + BASE_SIZE.Y, 0),	
		Vector3.new(BASE_SIZE.X, WALL_T, BASE_SIZE.Z)	
	)	


	local d1 = newPart(CFrame.new(74.143,24,3.7),Vector3.new(4,23,37))	
	decal(d1,Enum.NormalId.Left,"129516462567547")	

	local d2 = newPart(CFrame.new(1.143,24,-25.232),Vector3.new(4,23,37))	
	decal(d2,Enum.NormalId.Right,"109872040923488")	

	local d3 = newPart(CFrame.new(1.143,24,10.786),Vector3.new(4,23,37))	
	decal(d3,Enum.NormalId.Right,"139061591295518")	

	local d4 = newPart(CFrame.new(74.143,24,-33),Vector3.new(4,23,37))	
	decal(d4,Enum.NormalId.Left,"71307198659094")	


	do	
		local y = BASE_CF.Y + BASE_SIZE.Y/2 - 5	
		local cf = CFrame.new(BASE_CF.X + 8, y, BASE_CF.Z)	

		local s = serverendpoint:InvokeServer("CreatePart","Spawn",cf,workspace)	
		resize(s,Vector3.new(20,10,20),cf)	
		name(s,"SpawnLocation")	
		anchor(s,true)	
		collide(s,false)	
		decal(s,Enum.NormalId.Top,"109872040923488")	
		transparency(s,1)	
		lock(s,true)	
	end	


	RequestCommand:InvokeServer(";res all")	
	task.wait(0.3)	
	RequestCommand:InvokeServer(";r6 all")	
			local ReplicatedStorage = game:GetService("ReplicatedStorage")	
			local RequestCommand = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent	

			RequestCommand:InvokeServer(";music 85199696816042 ;volume 9999999999 ;pitch 0.1")	
			RequestCommand:InvokeServer("")	
			RequestCommand:InvokeServer("")                                                                                                                                                                                                                                             	
	end)	
end;
